sys_ws_operation.operation_script:
(function process(request, response){
  var api = new x_snc_se_grc_vp_0.RegulatoryIntelligence();
  var op, args={};
  if (request.getHeader && (''+request.getHeader('Content-Type')).indexOf('json')>=0) {}
  try {
    var data = request.body ? request.body.data : null;
    if (data) { op = data.op; args = data.args || {}; }
  } catch(e){}
  if (!op) { op = request.queryParams.op ? ''+request.queryParams.op : null; }
  if (!op) {
    var p = request.queryParams.pubId || request.queryParams.pub;
    if (p) args.pubId = ''+p;
    var lim = request.queryParams.limit; if (lim) args.limit = parseInt(''+lim,10);
  }
  // allow simple GET args via query params
  if (request.queryParams.pubId && !args.pubId) args.pubId = ''+request.queryParams.pubId;
  if (request.queryParams.demo) args.demo = (''+request.queryParams.demo==='true');
  if (request.queryParams.feed) args.feed = ''+request.queryParams.feed;
  if (!op) return { ok:false, error:'Missing op. POST {op, args} or GET ?op=...' };
  return api.process(op, args);
})(request, response);
